//go:build !tinygo

package wide

import (
	"bytes"
	"os"
	"os/exec"
	"path/filepath"
	"runtime"
	"testing"
)

// TestWidegen runs widegen into a temporary folder and makes sure that its
// files are the same, byte for byte, as the generated files of the package.
// It also makes sure that each file with the header of widegen is one that
// widegen writes. The test needs the go command, so it is skipped where a
// test cannot run it, such as wasm. TinyGo does not build it.
func TestWidegen(t *testing.T) {
	testGenerator(t, "widegen")
}

// TestFusegen does for fusegen, the tool of the fused programs of D98, what
// TestWidegen does for widegen.
func TestFusegen(t *testing.T) {
	testGenerator(t, "fusegen")
}

// testGenerator runs the tool internal/<tool> into a temporary folder, and
// makes sure that the package holds the same files, byte for byte, and no
// other file with the header of the tool.
func testGenerator(t *testing.T, tool string) {
	t.Helper()
	if runtime.GOOS == "js" || runtime.GOOS == "wasip1" {
		t.Skip("a test on wasm cannot run the go command")
	}
	goCmd, err := exec.LookPath("go")
	if err != nil {
		t.Skip("the go command is not in PATH")
	}
	dir := t.TempDir()
	cmd := exec.CommandContext(t.Context(), goCmd, "run", "./internal/"+tool, "-out", dir)
	// Build the tool for the host, also when the test runs for another
	// GOARCH or with GOEXPERIMENT=simd.
	cmd.Env = append(os.Environ(), "GOOS=", "GOARCH=", "GOEXPERIMENT=", "GOFLAGS=")
	if out, err := cmd.CombinedOutput(); err != nil {
		t.Fatalf("go run ./internal/%s: %v\n%s", tool, err, out)
	}
	generated, err := os.ReadDir(dir)
	if err != nil {
		t.Fatal(err)
	}
	want := map[string]bool{}
	for _, e := range generated {
		want[e.Name()] = true
		g, err := os.ReadFile(filepath.Join(dir, e.Name()))
		if err != nil {
			t.Fatal(err)
		}
		c, err := os.ReadFile(e.Name())
		if err != nil {
			t.Errorf("%s writes %s, and the package does not have it: %v", tool, e.Name(), err)
			continue
		}
		if !bytes.Equal(g, c) {
			t.Errorf("%s differs from the output of %s. Run go generate ./internal/wide", e.Name(), tool)
		}
	}
	files, err := filepath.Glob("*.go")
	if err != nil {
		t.Fatal(err)
	}
	for _, name := range files {
		if !want[name] && hasHeader(t, name, tool) {
			t.Errorf("%s has the header of %s, and %s does not write it", name, tool, tool)
		}
	}
}

// hasHeader reports whether the first line of the file name is the header
// of the tool.
func hasHeader(t *testing.T, name, tool string) bool {
	t.Helper()
	b, err := os.ReadFile(name)
	if err != nil {
		t.Fatal(err)
	}
	return bytes.HasPrefix(b, []byte("// Code generated by "+tool+"."))
}
